-- Lote 7 de 7 — 1875 negocios reales (datos_estimados=true)
-- Pegar completo en el SQL Editor de Supabase y darle Run.
on conflict (id) do update set
  nombre = excluded.nombre, categoria = excluded.categoria, tags = excluded.tags,
  precio = excluded.precio, duracion_min = excluded.duracion_min,
  lat = excluded.lat, lng = excluded.lng, comuna = excluded.comuna,
  energia = excluded.energia, exterior = excluded.exterior, indoor_alt = excluded.indoor_alt,
  accesible = excluded.accesible, experiencia_estimada = excluded.experiencia_estimada,
  hero_moment = excluded.hero_moment, horarios = excluded.horarios,
  punto_encuentro = excluded.punto_encuentro, datos_estimados = excluded.datos_estimados;
